<script setup>
import { computed, nextTick, onUnmounted, ref, watch } from 'vue'
import { labels, plans } from '../features.js'
import { dateKey, dateLabel, downloadCsv, money, number, statuses } from '../data.js'
import { auditHtml, bannerSvg, downloadFile, landingHtml, personalize, recipients } from '../workspace.js'
import { locale, localeTag, t, tr } from '../i18n.js'
import Icon from '../components/Icon.vue'
import Dialog from '../components/Dialog.vue'
import FeatureEditor from '../components/FeatureEditor.vue'
import VideoPreview from '../components/VideoPreview.vue'

const props=defineProps({module:Object,state:Object})
const emit=defineEmits(['save','action','notify','navigate'])
const tabId=ref(props.module.tabs[0].id),query=ref(''),selectedId=ref(null),editing=ref(null),deleting=ref(false),preview=ref(false),contact=ref({name:'',email:''}),captureMessage=ref(''),outreachConfirm=ref(false),localReply=ref('')
const config=computed(()=>props.module.tabs.find(tab=>tab.id===tabId.value)||props.module.tabs[0])
const rows=computed(()=>props.state.extensions.data[config.value.id]||[])
const visible=computed(()=>rows.value.filter(row=>[row.title,row.message,row.channel,row.detail].some(value=>String(value||'').toLowerCase().includes(query.value.toLowerCase()))))
const selected=computed(()=>visible.value.find(row=>row.id===selectedId.value)||visible.value[0])
const brand=computed(()=>props.state.extensions.data.brandkits.find(row=>row.status==='active'))
const label=value=>t(labels[value]||statuses[value]?.label||value)
async function tabKeys(event){
  if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key)||event.target.getAttribute('role')!=='tab')return
  event.preventDefault();const tabs=props.module.tabs,index=tabs.findIndex(tab=>tab.id===tabId.value)
  const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length
  tabId.value=tabs[next].id;await nextTick();document.getElementById('tab-'+tabId.value)?.focus()
}
const stamp=value=>value?new Intl.DateTimeFormat(localeTag(),{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—'
const selectionRecipients=computed(()=>selected.value&&config.value.id==='outreach'?recipients(props.state,selected.value):[])
const usedCredits=computed(()=>props.state.extensions.usage.reduce((sum,row)=>sum+row.credits,0))
const totalRecords=computed(()=>props.module.tabs.reduce((sum,tab)=>sum+(props.state.extensions.data[tab.id]?.length||0),0))
const speechAvailable=typeof window!=='undefined'&&'speechSynthesis' in window
const speaking=ref(false)
watch(()=>props.module.id,()=>{tabId.value=props.module.tabs[0].id;query.value='';selectedId.value=null;editing.value=null;preview.value=false;stopSpeech()})
watch(tabId,()=>{query.value='';selectedId.value=null;stopSpeech()})
watch(()=>selected.value?.id,()=>{localReply.value=selected.value?.reply||'';captureMessage.value='';contact.value={name:'',email:''}}, {immediate:true})
watch(()=>selected.value?.reply,value=>{localReply.value=value||''})
function action(action,payload={},done) {emit('action',{action,tab:config.value.id,id:selected.value?.id,payload},done)}
function save(item,done){emit('save',{tab:config.value.id,item},()=>{selectedId.value=item.id||null;done?.()})}
function download(kind) {
  const item=selected.value
  if(kind==='svg')downloadFile('marketlane-banner.svg',bannerSvg(item,props.state.profile),'image/svg+xml')
  if(kind==='html')downloadFile('marketlane-landing.html',landingHtml(item,props.state.profile,locale.value),'text/html')
  if(kind==='script')downloadFile('marketlane-storyboard.txt',[item.title,item.script,item.voiceover,item.captions].filter(Boolean).join('\n\n'),'text/plain;charset=utf-8')
  if(kind==='report'&&item.snapshot)downloadCsv('marketlane-report.csv',[[tr('Davr','Период','Period'),tr('Sana','Дата','Date'),'Reach','Leads','Spend','Revenue'],[item.snapshot.period,item.snapshot.date,item.snapshot.reach,item.snapshot.leads,item.snapshot.spend,item.snapshot.revenue]])
}
function openLanding(){preview.value=true;captureMessage.value='';action('visit')}
function capture(){action('capture',{...contact.value},()=>{captureMessage.value=tr('Murojaatingiz CRMga qo‘shildi.','Заявка добавлена в CRM.','Your inquiry was added to CRM.');contact.value={name:'',email:''}})}
function sendReply(){save({...selected.value,reply:localReply.value},()=>action('reply'))}
function speak(){
  stopSpeech()
  const text=selected.value?.voiceover
  if(!text?.trim())return emit('notify',tr('Diktor matnini kiriting.','Добавьте текст диктора.','Add voiceover text.'))
  const utterance=new SpeechSynthesisUtterance(text);utterance.lang=localeTag()
  const voice=window.speechSynthesis.getVoices().find(voice=>voice.lang.startsWith(locale.value))
  if(!voice)return emit('notify',tr('Bu til uchun brauzer ovozi o‘rnatilmagan.','Голос браузера для этого языка не установлен.','No browser voice is installed for this language.'))
  utterance.voice=voice;utterance.onend=()=>speaking.value=false;utterance.onerror=()=>speaking.value=false;speaking.value=true;window.speechSynthesis.speak(utterance)
}
function stopSpeech(){if(speechAvailable)window.speechSynthesis.cancel();speaking.value=false}
onUnmounted(stopSpeech)
function runAudit(){if(!selected.value.html?.trim())return emit('notify',tr('Tekshirish uchun HTML kiriting.','Вставьте HTML для проверки.','Paste HTML to run the check.'));action('seo',{audit:auditHtml(selected.value.html,selected.value.keyword)})}
const rate=(n,d)=>d?number(n/d*100,1)+'%':'—'
const workload=member=>props.state.tasks.filter(task=>task.owner.toLowerCase()===member.title.toLowerCase()&&task.status!=='done')
const detailFields=computed(()=>config.value.fields.filter(field=>!['title','image','html','color'].includes(field.key)))
</script>

<template>
  <div class="page-stack module-page" :class="'module-'+module.id">
    <header class="page-heading"><div><div class="eyebrow"><i></i>MARKETLANE / {{t(module.label).toUpperCase()}}</div><h1>{{t(module.label)}}</h1><p>{{t(module.subtitle)}}</p></div><div class="heading-actions"><span class="status-chip tone-purple"><i></i>{{tr('Lokal demo','Локальное демо','Local demo')}}</span><button v-if="config.fields.length" class="button button-primary" @click="editing={}"><Icon name="plus" :size="17"/>{{tr('Yangi qo‘shish','Добавить','Create new')}}</button></div></header>
    <div class="module-nav" role="tablist" :aria-label="t(module.label)" @keydown="tabKeys"><button v-for="tab in module.tabs" :key="tab.id" role="tab" :id="'tab-'+tab.id" :tabindex="tabId===tab.id?0:-1" :aria-selected="tabId===tab.id" :aria-controls="'panel-'+module.id" :class="{active:tabId===tab.id}" @click="tabId=tab.id"><Icon :name="tab.icon" :size="17"/><span>{{t(tab.label)}}</span><small v-if="state.extensions.data[tab.id]?.length">{{state.extensions.data[tab.id].length}}</small></button></div>
    <section :id="'panel-'+module.id" role="tabpanel" :aria-labelledby="'tab-'+config.id" class="module-panel">
      <div class="module-context"><span class="icon-tile" :class="'tone-'+module.color"><Icon :name="config.icon" :size="23"/></span><div><h2>{{t(config.label)}}</h2><p>{{t(config.description)}}</p></div></div>

      <template v-if="config.id==='billing'">
        <div class="billing-summary glass"><div><span class="eyebrow">{{tr('DEMO BALANS','ДЕМО-БАЛАНС','DEMO BALANCE')}}</span><h2>{{number(state.extensions.credits)}} <small>{{tr('kredit','кредитов','credits')}}</small></h2><p>{{tr('Ishlatilgan','Использовано','Used')}}: {{number(usedCredits)}}</p></div><button class="button button-secondary" @click="emit('action',{action:'credits'})"><Icon name="plus" :size="16"/>{{tr('100 demo kredit','100 демо-кредитов','100 demo credits')}}</button><div class="segmented"><button v-for="cycle in ['monthly','yearly']" :key="cycle" :aria-pressed="state.extensions.billingCycle===cycle" @click="emit('action',{action:'cycle',payload:{cycle}})">{{cycle==='monthly'?tr('Oylik','Месяц','Monthly'):tr('Yillik · −20%','Год · −20%','Yearly · −20%')}}</button></div></div>
        <div class="plan-grid"><article v-for="plan in plans" :key="plan.id" class="glass plan-card" :class="{chosen:state.extensions.plan===plan.id}"><span class="eyebrow">{{plan.name}}</span><h3>{{money(state.extensions.billingCycle==='yearly'?plan.price*12*.8:plan.price,2)}}<small>/{{state.extensions.billingCycle==='yearly'?tr('yil','год','year'):tr('oy','мес.','month')}}</small></h3><p>{{tr('Namunaviy tarif','Пример тарифа','Illustrative plan')}}</p><ul><li><Icon name="check" :size="16"/>{{plan.credits}} {{tr('oylik kredit','кредитов в месяц','monthly credits')}}</li><li><Icon name="check" :size="16"/>{{plan.users}} {{tr('foydalanuvchi','пользователей','users')}}</li><li><Icon name="check" :size="16"/>{{plan.accounts}} {{tr('ulangan hisob','подключённых аккаунтов','connected accounts')}}</li></ul><button class="button" :class="state.extensions.plan===plan.id?'button-secondary':'button-primary'" :disabled="state.extensions.plan===plan.id" @click="emit('action',{action:'plan',id:plan.id})">{{state.extensions.plan===plan.id?tr('Joriy demo tarif','Текущий демо-тариф','Current demo plan'):tr('Demo tanlash','Выбрать демо','Select demo')}}</button></article></div>
        <p class="subtle small">{{tr('Tarif tanlovi kreditlarni qayta to‘ldirmaydi va cheklovlarni qo‘llamaydi. Bu billing jarayoni maketi.','Смена тарифа не пополняет кредиты и не применяет лимиты. Это макет биллинга.','Selecting a plan does not refill credits or enforce plan limits. This is a billing prototype.')}}</p>
        <div class="glass detail-card"><h2>{{tr('Foydalanish tarixi','История использования','Usage history')}}</h2><div v-for="entry in state.extensions.usage" :key="entry.id" class="timeline-row"><Icon name="sparkles" :size="17"/><span><strong>{{entry.title}}</strong><small>{{stamp(entry.at)}} · {{entry.route}}</small></span><b>−{{entry.credits}}</b></div><p v-if="!state.extensions.usage.length" class="subtle">{{tr('Yordamchidan foydalanganda bu yerda tarix paydo bo‘ladi.','История появится после использования помощника.','Usage will appear here after you use the assistant.')}}</p></div>
      </template>

      <template v-else-if="config.id==='models'">
        <div class="route-grid"><article v-for="route in [{id:'text',icon:'file',label:tr('Matn va strategiya','Текст и стратегия','Text and strategy'),target:tr('Profilga mos mahalliy shablonlar','Локальные шаблоны с контекстом профиля','Local templates with profile context'),page:'assistant'},{id:'image',icon:'image',label:tr('Rasm va dizayn','Изображения и дизайн','Images and design'),target:tr('Banner maketi va yuklangan media','Макеты баннеров и загруженные медиа','Banner composition and uploaded media'),page:'assets'},{id:'video',icon:'play',label:tr('Video va audio','Видео и аудио','Video and audio'),target:tr('Storyboard va brauzer ovozi','Раскадровка и голос браузера','Storyboard and browser speech'),page:'storyboards'},{id:'analysis',icon:'chart',label:tr('Tahlil','Анализ','Analysis'),target:tr('Ish maydonidagi hisob-kitoblar','Расчёты по данным пространства','Workspace metric calculations'),page:'analytics'}]" :key="route.id" class="glass route-card"><span class="icon-tile tone-purple"><Icon :name="route.icon" :size="24"/></span><h3>{{route.label}}</h3><div class="route-connector"><span></span><Icon name="arrowDown" :size="17"/><span></span></div><p>{{route.target}}</p><span class="status-chip tone-neutral">{{tr('Demo yo‘nalish','Демо-маршрут','Demo route')}}</span><button class="button button-secondary" @click="['assets','storyboards'].includes(route.page)?tabId=route.page:emit('navigate',route.page)">{{tr('Ochish','Открыть','Open')}}<Icon name="arrowRight" :size="16"/></button></article></div>
      </template>

      <template v-else-if="config.readonly">
        <div class="glass detail-card"><div v-for="row in rows" :key="row.id" class="timeline-row"><span class="icon-tile" :class="row.status==='review'?'tone-amber':'tone-green'"><Icon :name="row.status==='review'?'clock':'check'" :size="17"/></span><div class="timeline-copy"><strong>{{row.title}}</strong><p>{{row.detail||row.message}}</p><small>{{stamp(row.at)}} · {{row.channel||label(row.action)}} · {{label(row.status)}}</small></div><div v-if="row.status==='review'" class="heading-actions"><button class="button button-primary button-compact" @click="emit('action',{action:'approve-run',tab:'runs',id:row.id})">{{tr('Tasdiqlash','Согласовать','Approve')}}</button><button class="button button-secondary button-compact" @click="emit('action',{action:'reject-run',tab:'runs',id:row.id})">{{tr('Rad etish','Отклонить','Reject')}}</button></div></div><div v-if="!rows.length" class="empty-state"><Icon name="clock" :size="30"/><h3>{{tr('Hozircha tarix yo‘q','История пока пуста','No activity yet')}}</h3><p>{{tr('Bajarilgan amallar shu yerda ko‘rinadi.','Выполненные действия появятся здесь.','Completed actions will appear here.')}}</p></div></div>
      </template>

      <template v-else>
        <div v-if="config.id==='rules'" class="automation-banner glass"><div><h3>{{tr('Nazoratli avtomatlashtirish','Управляемая автоматизация','Controlled automation')}}</h3><p>{{tr('Yoqilgan qoidalarni tekshiring. Tasdiq talab qiladigan amallar tarixda kutadi.','Проверьте активные правила. Действия с согласованием ожидают в журнале.','Check enabled rules. Actions needing approval wait in the run history.')}}</p></div><button class="button button-primary" @click="emit('action',{action:'run-rules'},()=>tabId='runs')"><Icon name="play" :size="16"/>{{tr('Hozir tekshirish','Проверить сейчас','Check now')}}</button></div>
        <div class="workbench-layout" :class="{'studio-layout':config.id==='assets'}">
          <aside class="glass record-browser"><div class="browser-toolbar"><Icon name="search" :size="17"/><input v-model="query" type="search" :placeholder="tr('Qidirish…','Поиск…','Search…')" :aria-label="tr('Yozuvlarni qidirish','Поиск записей','Search records')"/><small>{{visible.length}}</small></div><div class="browser-list"><button v-for="row in visible" :key="row.id" class="browser-record" :class="{selected:selected?.id===row.id}" @click="selectedId=row.id"><span v-if="config.id==='assets'" class="asset-swatch" :style="{background:row.color}"><img v-if="row.image" :src="row.image" alt=""/><Icon v-else name="image" :size="20"/></span><span v-else class="record-monogram">{{row.title?.slice(0,2).toUpperCase()}}</span><span class="browser-record-copy"><strong>{{row.title}}</strong><small>{{row.channel||label(row.status||row.role||row.trigger)||t(config.label)}}</small></span><span v-if="row.sentiment" class="sentiment-dot" :class="row.sentiment"></span><Icon v-else name="chevronRight" :size="14"/></button></div><button class="browser-add" @click="editing={}"><Icon name="plus" :size="16"/>{{tr('Yangi yozuv','Новая запись','New record')}}</button></aside>
          <section v-if="selected" class="glass detail-card record-detail"><header class="detail-heading"><div><span class="eyebrow">{{t(config.label)}}</span><h2>{{selected.title}}</h2></div><div class="heading-actions"><button class="icon-button" :aria-label="tr('Tahrirlash','Редактировать','Edit')" @click="editing={...selected}"><Icon name="pencil" :size="17"/></button><button class="icon-button danger-text" :aria-label="tr('O‘chirish','Удалить','Delete')" @click="deleting=true"><Icon name="trash" :size="17"/></button></div></header>

            <template v-if="config.id==='assets'">
              <div class="creative-preview" :class="'ratio-'+selected.format.replace(':','-')" :style="{'--creative-color':selected.color,fontFamily:brand?.font||'Arial'}"><img v-if="selected.image" :src="selected.image" :alt="selected.title"/><template v-else><span class="creative-brand">{{state.profile.name}}</span><h3>{{selected.headline||selected.title}}</h3><p>{{selected.body}}</p><span class="creative-mark">M<span>↗</span></span></template></div>
              <div class="detail-actions"><span class="status-chip tone-purple">{{selected.format}}</span><button v-if="!selected.image" class="button button-secondary" @click="download('svg')"><Icon name="download" :size="16"/>SVG</button><a v-else class="button button-secondary" :href="selected.image" download="marketlane-image"><Icon name="download" :size="16"/>{{tr('Yuklash','Скачать','Download')}}</a><button class="button button-primary" :disabled="!!selected.contentId&&state.content.some(row=>row.id===selected.contentId)" @click="action('content')"><Icon name="calendar" :size="16"/>{{tr('Kontent rejasiga','В контент-план','Add to calendar')}}</button></div>
            </template>
            <template v-else-if="config.id==='inbox'">
              <div class="conversation"><div class="conversation-meta"><span class="status-chip tone-blue">{{selected.channel}}</span><span class="status-chip" :class="'sentiment-'+selected.sentiment">{{label(selected.sentiment)}}</span></div><div class="message-bubble incoming">{{selected.message}}</div><div v-for="message in selected.messages||[]" :key="message.id" class="message-bubble outgoing">{{message.text}}<small>{{stamp(message.at)}} · {{tr('Demo','Демо','Demo')}}</small></div></div><label class="field"><span>{{tr('Javob','Ответ','Reply')}}</span><textarea v-model="localReply" rows="4" maxlength="12000" :placeholder="tr('Javob yozing…','Напишите ответ…','Write a reply…')"></textarea></label><div class="detail-actions"><button class="button button-secondary" @click="action('draft-reply',{},()=>localReply=selected.reply)"><Icon name="sparkles" :size="16"/>{{tr('Demo qoralama · 1 kredit','Демо-черновик · 1 кредит','Demo draft · 1 credit')}}</button><button class="button button-primary" :disabled="!localReply.trim()" @click="sendReply"><Icon name="send" :size="16"/>{{tr('Demo javob','Демо-ответ','Send demo reply')}}</button><button class="button button-secondary" :disabled="!!selected.leadId" @click="action('lead')"><Icon name="users" :size="16"/>{{tr('CRMga qo‘shish','Добавить в CRM','Add to CRM')}}</button></div>
            </template>
            <template v-else-if="config.id==='outreach'">
              <div class="outreach-preview"><span class="eyebrow">{{selected.channel}} · {{label(selected.segment)}}</span><h3>{{tr('Xabar ko‘rinishi','Предпросмотр сообщения','Message preview')}}</h3><p>{{personalize(selected.message,selectionRecipients[0]||{title:'Alex'},state.profile)}}</p></div><div class="recipient-strip"><Icon name="users" :size="18"/><strong>{{selectionRecipients.length}}</strong><span>{{tr('mos kontakt','подходящих контактов','eligible contacts')}}</span></div><div class="recipient-chips"><span v-for="lead in selectionRecipients.slice(0,8)" :key="lead.id">{{lead.title}}</span></div><button class="button button-primary" :disabled="!selectionRecipients.length||!selected.message?.trim()" @click="outreachConfirm=true"><Icon name="send" :size="16"/>{{tr('Demo yuborishni ko‘rish','Проверить демо-отправку','Review demo send')}}</button>
            </template>
            <template v-else-if="config.id==='landings'">
              <div class="landing-thumbnail" :style="{'--creative-color':selected.color}"><div class="mini-browser"><i></i><i></i><i></i><span>marketlane / {{selected.title}}</span></div><div class="mini-page"><span class="eyebrow">{{state.profile.name}}</span><h3>{{selected.headline}}</h3><p>{{selected.offer}}</p><span class="mock-button">{{selected.cta}}</span></div></div><div class="module-stats"><div><strong>{{selected.visits||0}}</strong><span>{{tr('Demo tashrif','Демо-посещения','Demo visits')}}</span></div><div><strong>{{selected.conversions||0}}</strong><span>{{tr('Arizalar','Заявки','Submissions')}}</span></div><div><strong>{{rate(selected.conversions,selected.visits)}}</strong><span>{{tr('Konversiya','Конверсия','Conversion')}}</span></div></div><div class="detail-actions"><button class="button button-primary" @click="openLanding"><Icon name="eye" :size="16"/>{{tr('Preview va forma','Предпросмотр и форма','Preview and form')}}</button><button class="button button-secondary" @click="download('html')"><Icon name="download" :size="16"/>HTML</button></div>
            </template>
            <template v-else-if="config.id==='experiments'">
              <div class="experiment-grid"><article v-for="variant in ['A','B']" :key="variant"><span class="experiment-letter">{{variant}}</span><h3>{{selected['variant'+variant]}}</h3><strong>{{rate(selected['conversions'+variant],selected['visits'+variant])}}</strong><p>{{selected['conversions'+variant]}} / {{selected['visits'+variant]}}</p><div class="experiment-bar"><span :style="{width:(selected['visits'+variant]?selected['conversions'+variant]/selected['visits'+variant]*100:0)+'%'}"></span></div></article></div><p class="detail-note">{{tr('Tashrif va konversiyalarni tahrirlash orqali natijani yangilang. Teng sharoit va yetarli namuna bo‘lmasdan g‘olib e’lon qilmang.','Обновите посещения и конверсии в редакторе. Для выбора победителя нужны равные условия и достаточная выборка.','Update visits and conversions in the editor. Choosing a winner requires comparable conditions and enough observations.')}}</p>
            </template>
            <template v-else-if="config.id==='positioning'">
              <div class="swot-grid"><article v-for="(key,i) in ['strengths','weaknesses','opportunities','threats']" :key="key" :class="'swot-'+i"><span>{{['S','W','O','T'][i]}}</span><h3>{{t(config.fields.find(field=>field.key===key).label)}}</h3><p>{{selected[key]||'—'}}</p></article></div><div class="positioning-usp"><span class="eyebrow">USP</span><p>{{selected.usp||'—'}}</p></div>
            </template>
            <template v-else-if="config.id==='rules'">
              <div class="rule-flow"><div><span class="icon-tile tone-blue"><Icon name="activity" :size="22"/></span><small>{{tr('AGAR','ЕСЛИ','IF')}}</small><strong>{{label(selected.trigger)}}</strong><span v-if="selected.trigger==='high-cpl'">{{money(selected.threshold,2)}}</span></div><Icon name="arrowRight" :size="24"/><div><span class="icon-tile tone-purple"><Icon name="shield" :size="22"/></span><small>{{tr('NAZORAT','КОНТРОЛЬ','CONTROL')}}</small><strong>{{label(selected.approval)}}</strong></div><Icon name="arrowRight" :size="24"/><div><span class="icon-tile tone-green"><Icon name="bolt" :size="22"/></span><small>{{tr('AMAL','ДЕЙСТВИЕ','ACTION')}}</small><strong>{{label(selected.action)}}</strong></div></div><div class="detail-actions"><span class="status-chip" :class="selected.enabled==='on'?'tone-green':'tone-neutral'">{{label(selected.enabled)}}</span><button class="button button-secondary" @click="save({...selected,enabled:selected.enabled==='on'?'off':'on'})">{{selected.enabled==='on'?tr('O‘chirish','Выключить','Disable'):tr('Yoqish','Включить','Enable')}}</button></div>
            </template>
            <template v-else>
              <VideoPreview v-if="config.id==='storyboards'" :item="selected" :profile="state.profile" :color="brand?.color" @notify="emit('notify',$event)"/>
              <div v-if="config.id==='brandkits'" class="brand-sample" :style="{background:selected.color,fontFamily:selected.font}"><span>{{selected.title}}</span><strong>Aa</strong><small>{{selected.color}} · {{selected.font}}</small></div>
              <div v-if="config.id==='members'" class="workload-card"><div><span class="record-monogram large">{{selected.title.slice(0,2).toUpperCase()}}</span><h3>{{label(selected.role)}}</h3></div><strong>{{workload(selected).length}} / {{selected.capacity}}</strong><p>{{tr('Ochiq vazifalar / haftalik sig‘im','Открытые задачи / недельная ёмкость','Open tasks / weekly capacity')}}</p><div class="capacity-bar"><span :style="{width:Math.min(100,selected.capacity?workload(selected).length/selected.capacity*100:0)+'%'}"></span></div><p v-if="workload(selected).length>selected.capacity" class="field-error">{{tr('Ish yuklamasi limitdan oshgan.','Нагрузка превышает лимит.','Workload exceeds capacity.')}}</p><button v-for="task in workload(selected)" :key="task.id" class="workload-task" @click="emit('navigate','tasks')">{{task.title}}<span>{{dateLabel(task.date)}}</span></button></div>
              <div v-if="config.id==='audiences'" class="module-stats"><div><strong>{{number(selected.followers-selected.previous)}}</strong><span>{{tr('O‘sish','Прирост','Growth')}}</span></div><div><strong>{{rate(selected.engagements,selected.reach)}}</strong><span>Engagement / reach</span></div></div>
              <div v-if="config.id==='partners'" class="module-stats"><div><strong>{{selected.leads?money(selected.fee/selected.leads,2):'—'}}</strong><span>CPL</span></div><div><strong>{{selected.fee?number(selected.revenue/selected.fee,2)+'×':'—'}}</strong><span>ROAS</span></div></div>
              <dl class="feature-details"><div v-for="field in detailFields" :key="field.key"><dt>{{t(field.label)}}</dt><dd v-if="field.type==='url'"><a v-if="/^https?:\/\//.test(selected[field.key]||'')" :href="selected[field.key]" target="_blank" rel="noopener noreferrer">{{selected[field.key]}} ↗</a><span v-else>—</span></dd><dd v-else>{{field.options?label(selected[field.key]):selected[field.key]||'—'}}</dd></div></dl>
              <template v-if="config.id==='competitors'"><button class="button button-secondary" @click="action('snapshot')"><Icon name="clock" :size="16"/>{{tr('Narx kuzatuvini saqlash','Сохранить наблюдение цены','Save price observation')}}</button><div v-for="point in selected.history||[]" :key="point.id" class="timeline-row"><Icon name="activity" :size="16"/><span><strong>{{money(point.price,2)}}</strong><small>{{stamp(point.at)}} · {{point.offer}}</small></span></div></template>
              <template v-if="config.id==='journeys'"><button class="button button-primary" @click="action('journey')"><Icon name="check" :size="16"/>{{tr('Kontaktga qo‘llash','Применить к контакту','Apply to contact')}}</button><small v-if="selected.appliedAt" class="subtle">{{stamp(selected.appliedAt)}}</small></template>
              <template v-if="config.id==='storyboards'"><div class="detail-actions"><button v-if="speechAvailable" class="button button-secondary" @click="speaking?stopSpeech():speak()"><Icon name="play" :size="16"/>{{speaking?tr('To‘xtatish','Остановить','Stop'):tr('Ovozli ko‘rish','Прослушать','Audio preview')}}</button><button class="button button-secondary" @click="download('script')"><Icon name="download" :size="16"/>TXT</button><button class="button button-primary" :disabled="!!selected.contentId" @click="action('content')">{{tr('Kontent rejasiga','В контент-план','Add to calendar')}}</button></div></template>
              <template v-if="config.id==='seo'"><button class="button button-primary" @click="runAudit"><Icon name="search" :size="16"/>{{tr('Lokal HTML tahlili','Локальный анализ HTML','Analyze local HTML')}}</button><div v-if="selected.audit" class="audit-grid"><div v-for="check in selected.audit" :key="check.key" :class="{passed:check.pass}"><Icon :name="check.pass?'check':'info'" :size="17"/><span>{{check.key}}</span><small>{{check.pass?tr('Topildi','Найдено','Found'):tr('Tekshiring','Проверьте','Review')}}</small></div></div></template>
              <template v-if="config.id==='reports'"><span v-if="selected.date<=dateKey()" class="status-chip tone-amber">{{tr('Hisobot vaqti keldi','Время отчёта','Report due')}}</span><div class="detail-actions"><button class="button button-primary" @click="action('report')"><Icon name="chart" :size="16"/>{{tr('Hisobot yaratish','Создать отчёт','Generate report')}}</button><button v-if="selected.snapshot" class="button button-secondary" @click="download('report')"><Icon name="download" :size="16"/>CSV</button></div><div v-if="selected.snapshot" class="module-stats"><div><strong>{{number(selected.snapshot.leads)}}</strong><span>{{tr('Leadlar','Лиды','Leads')}}</span></div><div><strong>{{money(selected.snapshot.spend,2)}}</strong><span>{{tr('Xarajat','Расходы','Spend')}}</span></div><div><strong>{{money(selected.snapshot.revenue,2)}}</strong><span>{{tr('Daromad','Доход','Revenue')}}</span></div></div></template>
            </template>
          </section>
          <section v-else class="glass empty-state feature-empty"><span class="icon-tile" :class="'tone-'+module.color"><Icon :name="config.icon" :size="30"/></span><h2>{{query?tr('Mos yozuv yo‘q','Совпадений нет','No matches'):tr('Birinchi yozuvdan boshlang','Начните с первой записи','Start with your first record')}}</h2><p>{{query?tr('Qidiruvni o‘zgartiring.','Измените поиск.','Try a different search.'):tr('Yangi yozuv qo‘shib, shu yo‘nalishda ishni boshlang.','Добавьте запись, чтобы начать работу.','Add a record to start working in this area.')}}</p><button v-if="!query" class="button button-primary" @click="editing={}"><Icon name="plus" :size="16"/>{{tr('Yaratish','Создать','Create')}}</button></section>
        </div>
      </template>
    </section>
    <FeatureEditor v-if="editing" :key="config.id+'-'+(editing.id||'new')" :config="config" :record="editing.id?editing:undefined" :profile="state.profile" :brand="brand" @close="editing=null" @save="save"/>
    <Dialog v-if="deleting" :title="tr('Yozuvni o‘chirish','Удалить запись','Delete record')" @close="deleting=false"><div class="dialog-body"><p>{{selected?.title}}</p><p class="subtle">{{tr('Bu yozuv ish maydonidan o‘chiriladi.','Запись будет удалена из пространства.','This record will be removed from the workspace.')}}</p><div class="dialog-actions"><button class="button button-secondary" @click="deleting=false">{{tr('Bekor qilish','Отмена','Cancel')}}</button><button class="button button-danger" @click="action('delete',{},()=>deleting=false)">{{tr('O‘chirish','Удалить','Delete')}}</button></div></div></Dialog>
    <Dialog v-if="preview&&selected" wide :title="tr('Landing preview','Предпросмотр лендинга','Landing preview')" @close="preview=false"><div class="dialog-body live-landing" :style="{'--creative-color':selected.color}"><span class="eyebrow">{{state.profile.name}}</span><h2>{{selected.headline}}</h2><p>{{selected.offer}}</p><form v-if="!captureMessage" class="record-form" @submit.prevent="capture"><label class="field"><span>{{tr('Ism','Имя','Name')}}</span><input v-model.trim="contact.name" required maxlength="110"/></label><label class="field"><span>Email</span><input v-model.trim="contact.email" type="email" required maxlength="150"/></label><button class="button button-primary">{{selected.cta||tr('Yuborish','Отправить','Submit')}}</button></form><p v-else class="landing-success" role="status"><Icon name="check" :size="20"/>{{captureMessage}}</p><small>{{tr('Mahalliy preview. Ariza faqat shu brauzerda saqlanadi.','Локальный предпросмотр. Заявка сохраняется только в этом браузере.','Local preview. Submissions are saved only in this browser.')}}</small></div></Dialog>
    <Dialog v-if="outreachConfirm" :title="tr('Demo yuborish','Демо-отправка','Demo send')" @close="outreachConfirm=false"><div class="dialog-body"><p>{{selected.title}} · {{selectionRecipients.length}} {{tr('kontakt','контактов','contacts')}}</p><p class="detail-note">{{tr('Har bir kontakt uchun shaxsiylashtirilgan yozuv tarixga qo‘shiladi. Bir xil xabar takror yuborilmaydi.','В историю добавятся персональные записи. Одинаковые сообщения не дублируются.','Personalized records will be added to history. Identical messages are not duplicated.')}}</p><div class="dialog-actions"><button class="button button-secondary" @click="outreachConfirm=false">{{tr('Bekor qilish','Отмена','Cancel')}}</button><button class="button button-primary" @click="action('outreach',{},()=>{outreachConfirm=false;tabId='deliveries'})">{{tr('Simulyatsiya qilish','Симулировать','Simulate send')}}</button></div></div></Dialog>
  </div>
</template>
